#pragma once

#include <OpenModel/Heat2DMesh.hpp>

#include <string>

/**
 * @file Heat2DGmsh.hpp
 * @brief Triangle meshes for Heat2DMesh generated by Gmsh (requires the Gmsh backend: OPENMODEL_BUILD_GMSH_BACKEND).
 *
 * Boundary tags: edges of the outer contour get tag 1; edges of every hole get tag 2. A curve is an outer contour when
 * its bounding box touches the bounding box of the surface on one of its sides. This holds for plates with holes that do
 * not touch the outer edges; a hole tangent to an outer side is classified as outer.
 */

namespace OpenModel::Heat2D {

/**
 * @brief Concentric annulus between two circles, built with the Gmsh OpenCASCADE kernel and meshed with linear triangles.
 * @param outerRadius  R > innerRadius > 0
 * @param innerRadius  a > 0
 * @param size         target element size, > 0
 * @param error        receives the reason when the mesh cannot be produced; left empty on success
 * @return the mesh; empty when there is an error
 */
TriangleMesh meshAnnulusGmsh(double outerRadius, double innerRadius, double size, std::string& error);

/**
 * @brief Imports a planar CAD file (STEP) that contains exactly one planar face, and meshes it with linear triangles.
 * @param path   path of the STEP file
 * @param size   target element size, > 0
 * @param error  receives the reason when the file cannot be used; left empty on success
 * @return the mesh; empty when there is an error
 */
TriangleMesh meshPlanarStepGmsh(const std::string& path, double size, std::string& error);

} // namespace OpenModel::Heat2D
